1	package dispatch
2	
3	import (
4		"errors"
5		"fmt"
6		"regexp"
7		"strings"
8	)
9	
10	var githubRepoSlugPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*/[A-Za-z0-9._-]+$`)
11	
12	func ResolveOptions(
13		flagLocal bool,
14		flagSince string,
15		flagUntil string,
16		flagAllBranches bool,
17		flagRepos []string,
18		flagVoice string,
19		flagInsecureHTTPAuth bool,
20		currentBranch func() (string, error),
21	) (Options, error) {
22		flagRepos = normalizeScopeValues(flagRepos)
23	
24		if flagLocal && len(flagRepos) > 0 {
25			return Options{}, errors.New("--repos cannot be used with --local")
26		}
27		if !flagLocal && flagAllBranches {
28			return Options{}, errors.New("--all-branches only applies to --local (cloud dispatch uses each repo's default branch)")
29		}
30		if !flagLocal {
31			if err := validateRepoSlugs(flagRepos); err != nil {
32				return Options{}, err
33			}
34		}
35		if !flagLocal && len(flagRepos) > CloudRepoLimit {
36			return Options{}, fmt.Errorf("--repos supports at most %d repos per dispatch", CloudRepoLimit)
37		}
38	
39		mode := ModeServer
40		if flagLocal {
41			mode = ModeLocal
42		}
43	
44		var branches []string
45		implicitCurrentBranch := false
46		if flagLocal && !flagAllBranches {
47			currentBranchName, err := currentBranch()
48			if err != nil {
49				return Options{}, err
50			}
51			branches = []string{currentBranchName}
52			implicitCurrentBranch = true
53		}
54	
55		return Options{
56			Mode:                  mode,
57			RepoPaths:             flagRepos,
58			Since:                 flagSince,
59			Until:                 flagUntil,
60			Branches:              branches,
61			AllBranches:           flagAllBranches,
62			ImplicitCurrentBranch: implicitCurrentBranch,
63			Voice:                 flagVoice,
64			InsecureHTTPAuth:      flagInsecureHTTPAuth,
65		}, nil
66	}
67	
68	func normalizeScopeValues(values []string) []string {
69		normalized := make([]string, 0, len(values))
70		seen := make(map[string]struct{}, len(values))
71		for _, value := range values {
72			value = strings.TrimSpace(value)
73			if value == "" {
74				continue
75			}
76			if _, ok := seen[value]; ok {
77				continue
78			}
79			seen[value] = struct{}{}
80			normalized = append(normalized, value)
81		}
82		return normalized
83	}
84	
85	func validateRepoSlugs(values []string) error {
86		for _, value := range values {
87			if !githubRepoSlugPattern.MatchString(value) {
88				return fmt.Errorf("invalid repo %q: expected owner/repo", value)
89			}
90		}
91		return nil
92	}
