150	func (c *CloudClient) CreateDispatch(ctx context.Context, reqBody CreateDispatchRequest) (*CreateDispatchResponse, error) {
151		var out CreateDispatchResponse
152		if err := c.doJSON(ctx, http.MethodPost, "/api/v1/dispatches/generate", reqBody, &out); err != nil {
153			return nil, err
154		}
155		return &out, nil
156	}
157	
158	func (c *CloudClient) doJSON(ctx context.Context, method, path string, reqBody, out any) error {
159		var body io.Reader
160		if reqBody != nil {
161			data, err := json.Marshal(reqBody)
162			if err != nil {
163				return fmt.Errorf("marshal request body: %w", err)
164			}
165			body = bytes.NewReader(data)
166		}
167	
168		req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
169		if err != nil {
170			return fmt.Errorf("create request: %w", err)
171		}
172		req.Header.Set("Accept", "application/json")
173		if reqBody != nil {
174			req.Header.Set("Content-Type", "application/json")
175		}
176		if c.token != "" {
177			req.Header.Set("Authorization", "Bearer "+c.token)
178		}
179	
180		resp, err := c.http.Do(req)
181		if err != nil {
182			return fmt.Errorf("%s %s: %w", method, path, err)
183		}
184		defer resp.Body.Close()
185	
186		if resp.StatusCode == http.StatusUnauthorized {
187			return errors.New("dispatch requires login — run `entire login`")
188		}
189		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
190			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) //nolint:errcheck // best-effort body read for error message
191			trimmed := strings.TrimSpace(string(body))
192			logging.Warn(ctx, "dispatch request failed", "method", method, "path", path, "status_code", resp.StatusCode)
193			if trimmed == "" {
194				return fmt.Errorf("dispatch service returned status %d", resp.StatusCode)
195			}
196			return fmt.Errorf("dispatch service returned status %d: %s", resp.StatusCode, strconv.Quote(trimmed))
197		}
198		if out == nil {
199			return nil
200		}
201		if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
202			return fmt.Errorf("decode response: %w", err)
203		}
204		return nil
205	}
