9	// Token is a single API token row returned by GET /api/v1/auth/tokens.
10	// Plaintext token values are never returned by the server — only metadata.
11	type Token struct {
12		ID         string  `json:"id"`
13		UserID     string  `json:"user_id"`
14		Name       string  `json:"name"`
15		Scope      string  `json:"scope"`
16		ExpiresAt  string  `json:"expires_at"`
17		LastUsedAt *string `json:"last_used_at"`
18		CreatedAt  string  `json:"created_at"`
19	}
20	
21	// TokensResponse is the envelope returned by GET /api/v1/auth/tokens.
22	type TokensResponse struct {
23		Tokens []Token `json:"tokens"`
24	}
25	
26	// ListTokens returns the authenticated user's non-expired API tokens.
27	// Backed by GET /api/v1/auth/tokens.
28	func (c *Client) ListTokens(ctx context.Context) ([]Token, error) {
29		resp, err := c.Get(ctx, "/api/v1/auth/tokens")
30		if err != nil {
31			return nil, fmt.Errorf("list tokens: %w", err)
32		}
33		defer resp.Body.Close()
34	
35		if err := CheckResponse(resp); err != nil {
36			return nil, fmt.Errorf("list tokens: %w", err)
37		}
38	
39		var out TokensResponse
40		if err := DecodeJSON(resp, &out); err != nil {
41			return nil, fmt.Errorf("list tokens: %w", err)
42		}
43		return out.Tokens, nil
44	}
45	
46	// RevokeCurrentToken revokes the bearer token used to authenticate this client.
47	// Backed by DELETE /api/v1/auth/tokens/current.
48	func (c *Client) RevokeCurrentToken(ctx context.Context) error {
49		resp, err := c.Delete(ctx, "/api/v1/auth/tokens/current")
50		if err != nil {
51			return fmt.Errorf("revoke current token: %w", err)
52		}
53		defer resp.Body.Close()
54	
55		if err := CheckResponse(resp); err != nil {
56			return fmt.Errorf("revoke current token: %w", err)
57		}
58		return nil
59	}
60	
61	// RevokeToken revokes the API token with the given id.
62	// Backed by DELETE /api/v1/auth/tokens/{id}.
63	func (c *Client) RevokeToken(ctx context.Context, id string) error {
64		resp, err := c.Delete(ctx, "/api/v1/auth/tokens/"+url.PathEscape(id))
65		if err != nil {
66			return fmt.Errorf("revoke token %s: %w", id, err)
67		}
68		defer resp.Body.Close()
69	
70		if err := CheckResponse(resp); err != nil {
71			return fmt.Errorf("revoke token %s: %w", id, err)
72		}
73		return nil
74	}
