92	func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
93		if response == nil {
94			return &Dispatch{}
95		}
96	
97		repos := make([]RepoGroup, 0, len(response.Repos))
98		for _, repo := range response.Repos {
99			sections := make([]Section, 0, len(repo.Sections))
100			for _, section := range repo.Sections {
101				bullets := make([]Bullet, 0, len(section.Bullets))
102				for _, bullet := range section.Bullets {
103					bullets = append(bullets, Bullet{
104						CheckpointID: bullet.CheckpointID,
105						Text:         bullet.Text,
106						Source:       bullet.Source,
107						Branch:       bullet.Branch,
108						CreatedAt:    parseAPITime(bullet.CreatedAt),
109						Labels:       append([]string(nil), bullet.Labels...),
110					})
111				}
112				sections = append(sections, Section{
113					Label:   section.Label,
114					Bullets: bullets,
115				})
116			}
117			repos = append(repos, RepoGroup{
118				FullName: repo.FullName,
119				URL:      githubRepoURL(repo.FullName),
120				Sections: sections,
121			})
122		}
123	
124		generatedText := strings.TrimSpace(response.GeneratedMarkdown)
125		if generatedText == "" {
126			generatedText = strings.TrimSpace(response.GeneratedText)
127		}
128	
129		return &Dispatch{
130			Window: Window{
131				NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
132				NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
133				FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
134				LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
135			},
136			CoveredRepos:  append([]string(nil), response.CoveredRepos...),
137			Repos:         repos,
138			GeneratedText: generatedText,
139		}
140	}
