142	func parseAPITime(value string) time.Time {
143		if value == "" {
144			return time.Time{}
145		}
146		parsed, err := time.Parse(time.RFC3339, value)
147		if err != nil {
148			return time.Time{}
149		}
150		return parsed
151	}
