29	func runLocal(ctx context.Context, opts Options) (*Dispatch, error) {
30		now := nowUTC()
31		sinceInput := strings.TrimSpace(opts.Since)
32		if sinceInput == "" {
33			sinceInput = "7d"
34		}
35		since, err := ParseSinceAtNow(sinceInput, now)
36		if err != nil {
37			return nil, err
38		}
39		until, err := ParseUntilAtNow(opts.Until, now)
40		if err != nil {
41			return nil, err
42		}
43		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
44		if !normalizedSince.Before(normalizedUntil) {
45			return nil, errors.New("--since must be before --until")
46		}
47	
48		repoRoots, err := resolveRepoRoots(ctx, opts.RepoPaths)
49		if err != nil {
50			return nil, err
51		}
52	
53		allCandidates := make([]candidate, 0)
54		var candidatesMu sync.Mutex
55		group, groupCtx := errgroup.WithContext(ctx)
56		for _, repoRoot := range repoRoots {
57			group.Go(func() error {
58				candidates, err := enumerateRepoCandidates(groupCtx, repoRoot, opts, normalizedSince, normalizedUntil)
59				if err != nil {
60					return err
61				}
62				candidatesMu.Lock()
63				allCandidates = append(allCandidates, candidates...)
64				candidatesMu.Unlock()
65				return nil
66			})
67		}
68		if err := group.Wait(); err != nil {
69			return nil, fmt.Errorf("enumerate repo candidates: %w", err)
70		}
71	
72		fallback := applyFallbackChain(allCandidates)
73		dispatch := &Dispatch{
74			CoveredRepos: coveredRepos(allCandidates),
75			Repos:        groupBulletsByRepo(fallback.Used),
76			Window: Window{
77				NormalizedSince:   normalizedSince,
78				NormalizedUntil:   normalizedUntil,
79				FirstCheckpointAt: firstAt(fallback.Used),
80				LastCheckpointAt:  lastAt(fallback.Used),
81			},
82		}
83	
84		text, err := generateLocalDispatch(ctx, dispatch, opts.Voice)
85		if err != nil {
86			return nil, err
87		}
88		if strings.TrimSpace(text) == "" {
89			return nil, errDispatchMissingMarkdown
90		}
91		dispatch.GeneratedText = text
92	
93		return dispatch, nil
94	}
