96	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
97		floored := since.Truncate(time.Minute)
98		ceiled := until.Truncate(time.Minute)
99		if !until.Equal(ceiled) {
100			ceiled = ceiled.Add(time.Minute)
101		}
102		return floored, ceiled
103	}
