105	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
106		if len(repoPaths) == 0 {
107			repoRoot, err := paths.WorktreeRoot(ctx)
108			if err != nil {
109				return nil, fmt.Errorf("not in a git repository: %w", err)
110			}
111			return []string{repoRoot}, nil
112		}
113	
114		roots := make([]string, 0, len(repoPaths))
115		for _, repoPath := range repoPaths {
116			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
117			output, err := cmd.Output()
118			if err != nil {
119				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
120			}
121			roots = append(roots, strings.TrimSpace(string(output)))
122		}
123		return roots, nil
124	}
