126	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
127		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
128		if err != nil {
129			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
130		}
131	
132		repoFullName, err := resolveRepoFullName(ctx, repo)
133		if err != nil {
134			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
135		}
136	
137		branches := opts.Branches
138		switch {
139		case opts.AllBranches:
140			branches, err = localBranchNames(repo)
141			if err != nil {
142				return nil, err
143			}
144		case len(branches) == 0:
145			currentBranch, err := currentBranchName(repo)
146			if err != nil {
147				return nil, err
148			}
149			branches = []string{currentBranch}
150		}
151		branchSet := make(map[string]struct{}, len(branches))
152		for _, branch := range branches {
153			branchSet[branch] = struct{}{}
154		}
155		reachableCheckpointIDs := map[string]struct{}{}
156		if opts.ImplicitCurrentBranch && !opts.AllBranches {
157			reachableCheckpointIDs, err = reachableCheckpointIDsInRange(ctx, repoRoot, branchLocalRevRange(ctx, repoRoot), since)
158			if err != nil {
159				return nil, err
160			}
161		}
162		commitSubjectsByCheckpoint, err := loadCommitSubjectsByCheckpoint(ctx, repoRoot, since)
163		if err != nil {
164			return nil, err
165		}
166	
167		store := checkpoint.NewGitStore(repo)
168		infos, err := store.ListCommitted(ctx)
169		if err != nil {
170			return nil, fmt.Errorf("list committed checkpoints: %w", err)
171		}
172	
173		candidates := make([]candidate, 0, len(infos))
174		for _, info := range infos {
175			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
176				continue
177			}
178	
179			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
180			if err != nil {
181				logging.Warn(ctx, "failed to read committed checkpoint for dispatch", "checkpoint_id", info.CheckpointID.String(), "error", err)
182				continue
183			}
184			if summary == nil {
185				continue
186			}
187			if _, onSelectedBranch := branchSet[summary.Branch]; !onSelectedBranch {
188				if !opts.ImplicitCurrentBranch {
189					continue
190				}
191				if _, reachable := reachableCheckpointIDs[info.CheckpointID.String()]; !reachable {
192					continue
193				}
194			}
195	
196			localSummary := ""
197			if len(summary.Sessions) > 0 {
198				latestIndex := len(summary.Sessions) - 1
199				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
200					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
201					if localSummary == "" {
202						localSummary = strings.TrimSpace(metadata.Summary.Intent)
203					}
204				}
205			}
206	
207			commitSubject := commitSubjectsByCheckpoint[info.CheckpointID.String()]
208			candidates = append(candidates, candidate{
209				CheckpointID:      info.CheckpointID.String(),
210				RepoFullName:      repoFullName,
211				Branch:            summary.Branch,
212				CreatedAt:         info.CreatedAt,
213				CommitSubject:     commitSubject,
214				LocalSummaryTitle: localSummary,
215			})
216		}
217	
218		return candidates, nil
219	}
