221	func reachableCheckpointIDsInRange(ctx context.Context, repoRoot, revRange string, since time.Time) (map[string]struct{}, error) {
222		cmd := exec.CommandContext(
223			ctx,
224			"git",
225			"-C",
226			repoRoot,
227			"log",
228			revRange,
229			"--since="+since.UTC().Format(time.RFC3339),
230			"--grep",
231			"Entire-Checkpoint:",
232			"--format=%B%x00",
233		)
234		output, err := cmd.Output()
235		if err != nil {
236			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
237		}
238	
239		reachable := make(map[string]struct{})
240		for _, message := range strings.Split(string(output), "\x00") {
241			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
242				reachable[checkpointID.String()] = struct{}{}
243			}
244		}
245		return reachable, nil
246	}
