248	// branchLocalRevRange returns a git log rev range that limits commits to
249	// those unique to the current branch — reachable from HEAD but not from the
250	// repository's default branch. Falls back to "HEAD" when no default branch
251	// can be resolved (e.g. a fresh repo with no main/master ref).
252	func branchLocalRevRange(ctx context.Context, repoRoot string) string {
253		base := defaultBranchRef(ctx, repoRoot)
254		if base == "" {
255			return "HEAD"
256		}
257		return base + "..HEAD"
258	}
259	
260	// defaultBranchRef resolves the repository's default branch, preferring
261	// origin/HEAD and falling back to the conventional main/master names. A
262	// candidate is only accepted if it is an ancestor of HEAD — otherwise a
263	// repo with an unconventional default (e.g. develop, trunk) would silently
264	// exclude the wrong history. Returns an empty string if nothing matches so
265	// callers can skip the exclusion.
266	func defaultBranchRef(ctx context.Context, repoRoot string) string {
267		if out, ok := runGitOutput(ctx, repoRoot, "symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"); ok {
268			ref := strings.TrimSpace(out)
269			if strings.HasPrefix(ref, "refs/remotes/") {
270				candidate := strings.TrimPrefix(ref, "refs/remotes/")
271				if isAncestorOfHEAD(ctx, repoRoot, candidate) {
272					return candidate
273				}
274			}
275		}
276		for _, candidate := range []string{"origin/main", "origin/master", "main", "master"} {
277			if _, ok := runGitOutput(ctx, repoRoot, "rev-parse", "--verify", "--quiet", candidate); !ok {
278				continue
279			}
280			if isAncestorOfHEAD(ctx, repoRoot, candidate) {
281				return candidate
282			}
283		}
284		return ""
285	}
286	
287	func isAncestorOfHEAD(ctx context.Context, repoRoot, ref string) bool {
288		_, ok := runGitOutput(ctx, repoRoot, "merge-base", "--is-ancestor", ref, "HEAD")
289		return ok
290	}
