292	func runGitOutput(ctx context.Context, repoRoot string, args ...string) (string, bool) {
293		fullArgs := append([]string{"-C", repoRoot}, args...)
294		out, err := exec.CommandContext(ctx, "git", fullArgs...).Output()
295		if err != nil {
296			return "", false
297		}
298		return string(out), true
299	}
