301	func resolveRepoFullName(ctx context.Context, repo *git.Repository) (string, error) {
302		remote, err := repo.Remote("origin")
303		if err != nil {
304			logging.Warn(ctx, "dispatch repo resolution failed", "step", "origin_remote", "error", err)
305			return "", fmt.Errorf("dispatch currently supports GitHub repositories with an origin remote: %w", err)
306		}
307		if len(remote.Config().URLs) == 0 {
308			return "", errors.New("dispatch currently supports GitHub repositories with an origin remote URL")
309		}
310	
311		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
312		if err != nil {
313			logging.Warn(ctx, "dispatch repo resolution failed", "step", "parse_origin_remote", "error", err)
314			return "", fmt.Errorf("dispatch currently supports GitHub origin remotes only: %w", err)
315		}
316		return owner + "/" + repoName, nil
317	}
