319	func currentBranchName(repo *git.Repository) (string, error) {
320		head, err := repo.Head()
321		if err != nil {
322			return "", fmt.Errorf("get HEAD: %w", err)
323		}
324		if !head.Name().IsBranch() {
325			return "", errors.New("not on a branch (detached HEAD)")
326		}
327		return head.Name().Short(), nil
328	}
