330	// localBranchNames returns the short names of the user's local branches,
331	// omitting the reserved "entire/" namespace used for internal refs.
332	func localBranchNames(repo *git.Repository) ([]string, error) {
333		iter, err := repo.Branches()
334		if err != nil {
335			return nil, fmt.Errorf("list local branches: %w", err)
336		}
337		defer iter.Close()
338	
339		var names []string
340		if err := iter.ForEach(func(ref *plumbing.Reference) error {
341			name := ref.Name().Short()
342			if strings.HasPrefix(name, checkpoint.ShadowBranchPrefix) {
343				return nil
344			}
345			names = append(names, name)
346			return nil
347		}); err != nil {
348			return nil, fmt.Errorf("iterate local branches: %w", err)
349		}
350		sort.Strings(names)
351		return names, nil
352	}
