354	func loadCommitSubjectsByCheckpoint(ctx context.Context, repoRoot string, since time.Time) (map[string]string, error) {
355		cmd := exec.CommandContext(
356			ctx,
357			"git",
358			"-C",
359			repoRoot,
360			"log",
361			"--all",
362			"--since="+since.UTC().Format(time.RFC3339),
363			"--grep",
364			"Entire-Checkpoint:",
365			"--format=%s%x00%B%x00%x00",
366		)
367		output, err := cmd.Output()
368		if err != nil {
369			return nil, fmt.Errorf("git log --grep: %w", err)
370		}
371	
372		subjects := make(map[string]string)
373		for _, record := range strings.Split(string(output), "\x00\x00") {
374			record = strings.TrimSuffix(record, "\x00")
375			if record == "" {
376				continue
377			}
378			parts := strings.SplitN(record, "\x00", 2)
379			if len(parts) != 2 {
380				continue
381			}
382			subject := strings.TrimSpace(parts[0])
383			for _, checkpointID := range trailers.ParseAllCheckpoints(parts[1]) {
384				id := checkpointID.String()
385				if _, ok := subjects[id]; ok {
386					continue
387				}
388				subjects[id] = subject
389			}
390		}
391		return subjects, nil
392	}
