394	func coveredRepos(candidates []candidate) []string {
395		if len(candidates) == 0 {
396			return nil
397		}
398	
399		repoSet := make(map[string]struct{}, len(candidates))
400		for _, candidate := range candidates {
401			if candidate.RepoFullName == "" {
402				continue
403			}
404			repoSet[candidate.RepoFullName] = struct{}{}
405		}
406	
407		repos := make([]string, 0, len(repoSet))
408		for repoFullName := range repoSet {
409			repos = append(repos, repoFullName)
410		}
411		sort.Strings(repos)
412		return repos
413	}
