415	func groupBulletsByRepo(used []repoBullet) []RepoGroup {
416		repoMap := make(map[string]map[string][]Bullet)
417		for _, item := range used {
418			if _, ok := repoMap[item.RepoFullName]; !ok {
419				repoMap[item.RepoFullName] = make(map[string][]Bullet)
420			}
421			label := "Updates"
422			if len(item.Bullet.Labels) > 0 && strings.TrimSpace(item.Bullet.Labels[0]) != "" {
423				label = item.Bullet.Labels[0]
424			}
425			repoMap[item.RepoFullName][label] = append(repoMap[item.RepoFullName][label], item.Bullet)
426		}
427	
428		repoNames := make([]string, 0, len(repoMap))
