369	// newLazyOptions returns a func that runs loader once (under sync.Once) and
370	// returns the cached result on subsequent calls. Safe for concurrent use.
371	func newLazyOptions(loader func() []huh.Option[string]) func() []huh.Option[string] {
372		var (
373			once    sync.Once
374			options []huh.Option[string]
375		)
376		return func() []huh.Option[string] {
377			once.Do(func() {
378				options = loader()
379			})
380			return options
381		}
