403	func normalizeDispatchWizardSelections(values []string) []string {
404		normalized := make([]string, 0, len(values))
405		seen := make(map[string]struct{}, len(values))
406		for _, value := range values {
407			value = strings.TrimSpace(value)
408			if value == "" {
409				continue
410			}
411			if _, ok := seen[value]; ok {
412				continue
413			}
414			seen[value] = struct{}{}
415			normalized = append(normalized, value)
416		}
417		return normalized
418	}
