420	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
421		rootSet := map[string]struct{}{currentRepo: {}}
422		parent := filepath.Dir(currentRepo)
423	
424		entries, err := os.ReadDir(parent)
425		if err == nil {
426			candidates := make([]string, 0, len(entries))
427			for _, entry := range entries {
428				if !entry.IsDir() {
429					continue
430				}
431				candidate := filepath.Join(parent, entry.Name())
432				if _, statErr := os.Stat(filepath.Join(candidate, ".git")); statErr != nil {
433					continue
434				}
435				candidates = append(candidates, candidate)
436			}
437	
438			resolved := make([]string, len(candidates))
439			sem := make(chan struct{}, dispatchWizardRepoDiscoveryConcurrencyLimit)
440			var wg sync.WaitGroup
441			wg.Add(len(candidates))
442			for i, candidate := range candidates {
443				sem <- struct{}{}
444				go func(i int, candidate string) {
445					defer wg.Done()
446					defer func() { <-sem }()
447					if repoRoot, resolveErr := resolveDispatchWizardTopLevel(ctx, candidate); resolveErr == nil {
448						resolved[i] = repoRoot
449					}
450				}(i, candidate)
451			}
452			wg.Wait()
453			for _, repoRoot := range resolved {
454				if repoRoot != "" {
455					rootSet[repoRoot] = struct{}{}
456				}
457			}
458		}
459	
460		repoRoots := make([]string, 0, len(rootSet))
461		for repoRoot := range rootSet {
462			repoRoots = append(repoRoots, repoRoot)
463		}
464		sort.Slice(repoRoots, func(i, j int) bool {
465			if repoRoots[i] == currentRepo {
466				return true
467			}
468			if repoRoots[j] == currentRepo {
469				return false
470			}
471			return filepath.Base(repoRoots[i]) < filepath.Base(repoRoots[j])
472		})
473		return repoRoots
474	}
475	
476	func discoverLocalRepoSlugs(ctx context.Context, currentRepo string) []string {
477		repoRoots := discoverLocalRepoRoots(ctx, currentRepo)
478		repoSlugs := make([]string, 0, len(repoRoots))
479		seenRepoSlugs := make(map[string]struct{}, len(repoRoots))
480		for _, repoRoot := range repoRoots {
481			repoSlug := discoverRepoSlug(repoRoot)
482			if repoSlug == "" {
483				continue
484			}
485			if _, ok := seenRepoSlugs[repoSlug]; ok {
486				continue
487			}
488			seenRepoSlugs[repoSlug] = struct{}{}
489			repoSlugs = append(repoSlugs, repoSlug)
490		}
491		return repoSlugs
492	}
493	
494	func resolveGitTopLevel(ctx context.Context, path string) (string, error) {
495		cmd := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
496		output, err := cmd.Output()
497		if err != nil {
498			return "", fmt.Errorf("git rev-parse --show-toplevel: %w", err)
499		}
500		return strings.TrimSpace(string(output)), nil
501	}
502	
503	// discoverAuthenticatedDispatchWizardRepos drops repos with zero checkpoints —
504	// dispatching them would produce nothing. Server order (recent-first) is
505	// preserved.
506	func discoverAuthenticatedDispatchWizardRepos(ctx context.Context) ([]string, error) {
507		repos, err := listDispatchWizardRepoResources(ctx)
508		if err != nil {
509			logging.Warn(ctx, "dispatch wizard repo list failed", "error", err)
510			return nil, err
511		}
512	
513		slugs := make([]string, 0, len(repos))
514		for _, repo := range repos {
515			if repo.CheckpointCount <= 0 {
516				continue
517			}
518			slug := strings.TrimSpace(repo.FullName)
519			if slug == "" {
520				continue
521			}
522			slugs = append(slugs, slug)
523		}
524		return slugs, nil
525	}
526	
527	func discoverRepoSlug(repoRoot string) string {
528		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
529		if err != nil {
530			return ""
531		}
532		remote, err := repo.Remote("origin")
533		if err != nil || len(remote.Config().URLs) == 0 {
534			return ""
535		}
536		owner, repoName, err := searchpkg.ParseGitHubRemote(remote.Config().URLs[0])
537		if err != nil {
538			return ""
539		}
540		return owner + "/" + repoName
541	}
